INSERT IGNORE INTO `items` (`item`, `label`, `limit`, `can_remove`, `type`, `usable`, `useExpired`, `groupId`, `rarityId`, `metadata`, `desc`, `degradation`, `durability`, `instructions`, `weight`) VALUES
  ('pet_armadillo', 'Armadillo', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Armoured, unhurried, and entirely unbothered by your opinion.', 0, NULL, NULL, 1.00),
  ('pet_badger', 'Badger', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Digs first and reconsiders later. Afraid of nothing its own size or larger.', 0, NULL, NULL, 1.00),
  ('pet_beaver', 'Beaver', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Will try to dam any water you camp beside. Cannot be reasoned with.', 0, NULL, NULL, 1.00),
  ('pet_bluejay', 'Blue Jay', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Loud, bright and spoiling for a fight with birds twice its size.', 0, NULL, NULL, 1.00),
  ('pet_boar', 'Boar', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Bad tempered, thick skinned, and a poor choice to startle.', 0, NULL, NULL, 1.00),
  ('pet_buck', 'Buck', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Carries its antlers like a warning. Most things take it as one.', 0, NULL, NULL, 1.00),
  ('pet_cardinal', 'Cardinal', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'A red flame in a bare tree. Easier to hear than to spot.', 0, NULL, NULL, 1.00),
  ('pet_cat', 'Cat', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Follows when it suits. Sits exactly where you were about to.', 0, NULL, NULL, 1.00),
  ('pet_chicken', 'Chicken', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Follows you for grain and nothing else. Honest about it.', 0, NULL, NULL, 1.00),
  ('pet_chipmunk', 'Chipmunk', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Cheeks full, always. Will empty your satchel given an hour.', 0, NULL, NULL, 1.00),
  ('pet_collie', 'Collie', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Watchful, tidy and quicker than it looks. Herds by suggestion rather than force.', 0, NULL, NULL, 1.00),
  ('pet_coonhound', 'Bluetick Coonhound', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Nose down from dawn to dusk. Follows a scent long after you have lost interest.', 0, NULL, NULL, 1.00),
  ('pet_cow', 'Cow', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Slow, warm and entirely uninterested in your plans.', 0, NULL, NULL, 1.00),
  ('pet_crow', 'Crow', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Remembers faces, holds grudges, and tells the other crows.', 0, NULL, NULL, 1.00),
  ('pet_cur', 'Catahoula Cur', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Half working dog, half swamp ghost. Takes to water and to trouble alike.', 0, NULL, NULL, 1.00),
  ('pet_deer', 'Deer', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Skittish in open country, calm once it knows your step.', 0, NULL, NULL, 1.00),
  ('pet_donkey', 'Donkey', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Stubborn past persuasion, and right about the footing more often than you.', 0, NULL, NULL, 1.00),
  ('pet_fox', 'Fox', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Trots at your heel as though it were its own idea. It was.', 0, NULL, NULL, 1.00),
  ('pet_foxhound', 'American Foxhound', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Bred to run all day and bay at what it finds. Rarely quiet, never lost.', 0, NULL, NULL, 1.00),
  ('pet_frog', 'Bullfrog', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Bellows at dusk loud enough to carry a mile. Good company by a creek.', 0, NULL, NULL, 1.00),
  ('pet_gila', 'Gila Monster', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Beaded, patient and venomous. Bites once and does not let go.', 0, NULL, NULL, 1.00),
  ('pet_goat', 'Goat', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Eats your rope, your hat and your patience. Climbs what it should not.', 0, NULL, NULL, 1.00),
  ('pet_goose', 'Goose', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Guards better than most dogs and holds a grudge far longer.', 0, NULL, NULL, 1.00),
  ('pet_hobo', 'Hobo Dog', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Rode in on a freight car and never got off. Owes nobody a thing.', 0, NULL, NULL, 1.00),
  ('pet_hound', 'Hound', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Sleeps by the fire, wakes for a scent. The rest is negotiable.', 0, NULL, NULL, 1.00),
  ('pet_hound_10', 'Hound (Variant 10)', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'The same old hound in a coat of its own. Rename it once you have met it.', 0, NULL, NULL, 1.00),
  ('pet_husky', 'Husky', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Built for weather that kills. Complains loudly about anything warmer.', 0, NULL, NULL, 1.00),
  ('pet_iguana', 'Iguana', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Watches everything, moves for nothing, and judges quietly.', 0, NULL, NULL, 1.00),
  ('pet_iguana_d', 'Desert Iguana', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Lives on hot stone and asks for nothing but the sun.', 0, NULL, NULL, 1.00),
  ('pet_lab', 'Labrador', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Cheerful past all reason. Will swim in anything wet enough to hold it.', 0, NULL, NULL, 1.00),
  ('pet_leg_beaver', 'Legendary Beaver', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Older and a good deal larger than any beaver has business being.', 0, NULL, NULL, 1.00),
  ('pet_leg_bighornram', 'Legendary Bighorn Ram', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Came down off the high rocks one winter and never went back up.', 0, NULL, NULL, 1.00),
  ('pet_leg_bison', 'Legendary Bison', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'The last of a herd that once darkened the plains. Walks alone now.', 0, NULL, NULL, 1.00),
  ('pet_leg_blackbeaver', 'Legendary Black Beaver', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Dark-pelted and near invisible at dusk. Works the water while you sleep.', 0, NULL, NULL, 1.00),
  ('pet_leg_blackcougar', 'Legendary Black Cougar', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Black as a closed room. Only the eyes give it away.', 0, NULL, NULL, 1.00),
  ('pet_leg_boa', 'Legendary Boa', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Ten feet of patient muscle. Goes where it likes and takes its time getting there.', 0, NULL, NULL, 1.00),
  ('pet_leg_buck', 'Legendary Buck', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Antlers counted in double figures. Has outlived every hunter who tried for them.', 0, NULL, NULL, 1.00),
  ('pet_leg_bullgator', 'Legendary Bullgator', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Twelve feet of bad temper hauled out of the bayou. Nothing hunts it twice.', 0, NULL, NULL, 1.00),
  ('pet_leg_chalkhornram', 'Legendary Chalk Horn Ram', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Horns white as chalk and hard as an anvil. Comes down mountains sideways.', 0, NULL, NULL, 1.00),
  ('pet_leg_cogiboar', 'Legendary Cogi Boar', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Scarred from a hundred fights it started. Still looking for the next one.', 0, NULL, NULL, 1.00),
  ('pet_leg_coyote', 'Legendary Coyote', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Sang outside camps for a decade before it finally followed one home.', 0, NULL, NULL, 1.00),
  ('pet_leg_crossfox', 'Legendary Cross Fox', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Dark cross over the shoulders, silver at the brush. Rare even in the stories.', 0, NULL, NULL, 1.00),
  ('pet_leg_deadlybear', 'Legendary Deadly Bear', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Killed more men than the winter did. Walks at your shoulder now.', 0, NULL, NULL, 1.00),
  ('pet_leg_elk', 'Legendary Elk', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Crowned with antlers that catch the light. Steps like it owns the ridge.', 0, NULL, NULL, 1.00),
  ('pet_leg_emeraldwolf', 'Legendary Emerald Wolf', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Green fire in its eyes and a pelt no trapper could put a name to.', 0, NULL, NULL, 1.00),
  ('pet_leg_fox', 'Legendary Fox', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Silver-tipped and quicker than the eye. Every trapper has a story, none has the pelt.', 0, NULL, NULL, 1.00),
  ('pet_leg_ghostpanther', 'Legendary Ghost Panther', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Pale enough to look through. Bounty hunters stopped filing reports on it.', 0, NULL, NULL, 1.00),
  ('pet_leg_greatboar', 'Legendary Great Boar', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'The boar the old hunters warned about. Still carries their arrowheads.', 0, NULL, NULL, 1.00),
  ('pet_leg_greathornram', 'Legendary GreatHorn Ram', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'The horns curl full circle. It has never needed to use them twice.', 0, NULL, NULL, 1.00),
  ('pet_leg_greybeaver', 'Legendary Grey Beaver', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Grey as river stone and just as patient. Fells trees a man would need an axe for.', 0, NULL, NULL, 1.00),
  ('pet_leg_igugacougar', 'Legendary Iguga Cougar', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Moves like smoke through the rocks. You hear it only after it has passed.', 0, NULL, NULL, 1.00),
  ('pet_leg_katataelk', 'Legendary Katata Elk', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Antlers wide as a wagon. Bugles loud enough to turn a whole valley.', 0, NULL, NULL, 1.00),
  ('pet_leg_knightmoose', 'Legendary Knight Moose', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Armoured in scar tissue and antler. Has walked away from every hunt.', 0, NULL, NULL, 1.00),
  ('pet_leg_midnightpawcoyote', 'Legendary Midnight Paw Coyote', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Pale coat, black feet. Leaves tracks that stop making sense.', 0, NULL, NULL, 1.00),
  ('pet_leg_milkcoyote', 'Legendary Milk Coyote', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'White as spilled milk and twice as hard to catch.', 0, NULL, NULL, 1.00),
  ('pet_leg_moose', 'Legendary Moose', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Stands taller than a man on horseback and yields to nothing at all.', 0, NULL, NULL, 1.00),
  ('pet_leg_mudrunnerbuck', 'Legendary Mudrunner Buck', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Comes out of the marsh caked to the shoulder. Faster than the ground allows.', 0, NULL, NULL, 1.00),
  ('pet_leg_nightwalkerpanther', 'Legendary Nightwalker Panther', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Hunts the hours nobody else is awake for. Never seen twice in one place.', 0, NULL, NULL, 1.00),
  ('pet_leg_onyxwolf', 'Legendary Onyx Wolf', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Black as struck coal. Led a pack that was never found.', 0, NULL, NULL, 1.00),
  ('pet_leg_otafox', 'Legendary Ota Fox', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'A coat of impossible colour. Trappers argued for years over whether it was real.', 0, NULL, NULL, 1.00),
  ('pet_leg_owizabear', 'Legendary Owiza Bear', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Named in a language older than the territory. Answers to nothing.', 0, NULL, NULL, 1.00),
  ('pet_leg_payatabison', 'Legendary Payata Bison', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Pale-shouldered and enormous. The plains part around it.', 0, NULL, NULL, 1.00),
  ('pet_leg_pronghorn', 'Legendary Pronghorn', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Outran horses, dogs and men alike. Then chose to stop.', 0, NULL, NULL, 1.00),
  ('pet_leg_rattlesnake', 'Legendary Rattlesnake', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Rattles once, as a courtesy. There is not usually a second warning.', 0, NULL, NULL, 1.00),
  ('pet_leg_redstreakcoyote', 'Legendary Red Streak Coyote', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'A rust-red streak across the badlands. Laughs at the moon and at you.', 0, NULL, NULL, 1.00),
  ('pet_leg_ridgebackspiritbear', 'Legendary Ridgeback Spirit Bear', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'White-ridged and spoken of in whispers. Some say it is not entirely here.', 0, NULL, NULL, 1.00),
  ('pet_leg_ruddymoose', 'Legendary Ruddy Moose', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Deep red at the flank. Stands chest-deep in water and dares you to come in.', 0, NULL, NULL, 1.00),
  ('pet_leg_rutilehornram', 'Legendary Rutile Horn Ram', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Horns shot through with red gold. Worth a fortune on any wall but yours.', 0, NULL, NULL, 1.00),
  ('pet_leg_sapacougar', 'Legendary Sapa Cougar', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Dark-masked and silent. The kind of thing that watches camps from the ridge.', 0, NULL, NULL, 1.00),
  ('pet_leg_shadowbuck', 'Legendary Shadow Buck', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Dark-coated and gone the moment you look straight at it.', 0, NULL, NULL, 1.00),
  ('pet_leg_sunalligator', 'Legendary Sun Alligator', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Pale as bleached bone from the sun-scorched shallows. Older than the swamp roads.', 0, NULL, NULL, 1.00),
  ('pet_leg_tatankabison', 'Legendary Tatanka Bison', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Sacred to those who named it. Two thousand pounds of walking history.', 0, NULL, NULL, 1.00),
  ('pet_leg_tatankabison2', 'Legendary Tatanka Bison', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Another of the sacred herd. Just as old, and just as unmoved by you.', 0, NULL, NULL, 1.00),
  ('pet_leg_wakpaboar', 'Legendary Wakpa Boar', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Named by the river people for the water it never strays far from.', 0, NULL, NULL, 1.00),
  ('pet_leg_wildhog', 'Legendary Wildhog', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Hunted for years and never taken. Now it walks behind you instead.', 0, NULL, NULL, 1.00),
  ('pet_leg_wolf', 'Legendary Wolf', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'The one the ranchers blamed for everything. Most of it was true.', 0, NULL, NULL, 1.00),
  ('pet_lion', 'Mangy Lion', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Came off a travelling circus wagon and never found its way back. Moth-eaten, half-starved, and still the largest thing for miles.', 0, NULL, NULL, 1.00),
  ('pet_liondog', 'Lion Dog', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Clipped like a lion by somebody with time and shears. Carries it well.', 0, NULL, NULL, 1.00),
  ('pet_muskrat', 'Muskrat', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Smells of the river and much prefers it that way.', 0, NULL, NULL, 1.00),
  ('pet_owl', 'Owl', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Silent in flight and awake when you are not. Watches the treeline.', 0, NULL, NULL, 1.00),
  ('pet_parrot', 'Parrot', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Repeats the worst thing it has heard you say, usually in company.', 0, NULL, NULL, 1.00),
  ('pet_pig', 'Pig', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Smarter than the dog and aware of it. Will eat anything you drop.', 0, NULL, NULL, 1.00),
  ('pet_pigeon', 'Pigeon', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Finds its way home from anywhere. Home, apparently, is you.', 0, NULL, NULL, 1.00),
  ('pet_poodle', 'Poodle', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Curled and groomed and far tougher than the haircut suggests.', 0, NULL, NULL, 1.00),
  ('pet_possum', 'Possum', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Plays dead convincingly. Occasionally is.', 0, NULL, NULL, 1.00),
  ('pet_pronghorn', 'Pronghorn', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Faster than anything else out here, and quietly aware of it.', 0, NULL, NULL, 1.00),
  ('pet_rabbit', 'Rabbit', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Nervous, quick, and gone at the first loud noise. Comes back for food.', 0, NULL, NULL, 1.00),
  ('pet_raccoon', 'Raccoon', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Clever hands and no morals whatever. Check your pockets afterwards.', 0, NULL, NULL, 1.00),
  ('pet_ram', 'Bighorn Ram', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Settles arguments with its skull. Has never lost one.', 0, NULL, NULL, 1.00),
  ('pet_rat', 'Rat', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Nobody wants one. Outlives everything that does.', 0, NULL, NULL, 1.00),
  ('pet_raven', 'Raven', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Watches you the way a creditor does. Collects anything that shines.', 0, NULL, NULL, 1.00),
  ('pet_retriever', 'Bay Retriever', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Comes back with whatever you sent it after, wet through and pleased about it.', 0, NULL, NULL, 1.00),
  ('pet_robin', 'Robin', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Turns up when the frost breaks. Pulls worms with grim determination.', 0, NULL, NULL, 1.00),
  ('pet_rooster', 'Rooster', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Announces dawn an hour early and will not be corrected.', 0, NULL, NULL, 1.00),
  ('pet_rufus', 'Rufus', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Answers to Rufus. Has never explained where he came from.', 0, NULL, NULL, 1.00),
  ('pet_sheep', 'Sheep', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Follows without asking where. Wool worth more than the trouble.', 0, NULL, NULL, 1.00),
  ('pet_sheep_bow', 'Pink Bow Sheep', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'A merino ewe in a pink ribbon. Somebody loved her. Best not ask who.', 0, NULL, NULL, 1.00),
  ('pet_shepherd', 'Australian Shepherd', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Herds anything that moves, including you. Keeps one eye on the horizon.', 0, NULL, NULL, 1.00),
  ('pet_shepherd_black', 'Black Australian Shepherd', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Dark as a moonless field, and just as hard to keep track of after dusk. (coat 2)', 0, NULL, NULL, 1.00),
  ('pet_shepherd_merle', 'Merle Australian Shepherd', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'A marbled grey coat no two of which fall the same way. Herds anything that moves, including you. (coat 0)', 0, NULL, NULL, 1.00),
  ('pet_shepherd_red', 'Red Australian Shepherd', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Copper through and through, and twice as stubborn. Keeps one eye on the horizon. (coat 1)', 0, NULL, NULL, 1.00),
  ('pet_skunk', 'Skunk', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Loyal, affectionate, and a standing threat to everyone downwind.', 0, NULL, NULL, 1.00),
  ('pet_snake', 'Snake', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Coils in the shade and asks only that you watch where you step.', 0, NULL, NULL, 1.00),
  ('pet_songbird', 'Songbird', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Sings the morning in whether you wanted it or not.', 0, NULL, NULL, 1.00),
  ('pet_sparrow', 'Sparrow', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Small, plain and everywhere. Outlives grander birds by going unnoticed.', 0, NULL, NULL, 1.00),
  ('pet_squirrel', 'Squirrel', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Buries things it will never find again. Rides on the saddle horn.', 0, NULL, NULL, 1.00),
  ('pet_street', 'Street Dog', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Learned the alleys before it learned its name. Trusts you slowly.', 0, NULL, NULL, 1.00),
  ('pet_toad', 'Toad', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Sits. Blinks. Occasionally moves. Asks nothing of anyone.', 0, NULL, NULL, 1.00),
  ('pet_turkey', 'Turkey', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Larger and more argumentative than it has any right to be.', 0, NULL, NULL, 1.00),
  ('pet_turtle', 'Turtle', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Slow enough to lose in open country. Worth the wait.', 0, NULL, NULL, 1.00),
  ('vanagandr', 'Vanagandr', 1, 1, 'item_standard', 1, 0, 1, 5, '{}', 'Silver-pale and cold to look at. Runs ahead of the storms.', 0, NULL, NULL, 1.00);
