-- pup-misc / pets | install.sql
--
-- Creates:  pet_coats (the coat each character drew for a pet with a `variants` pool)
-- Items:    one whistle item per entry in PetsConfig.Pets (config/pets/pets.lua). usable MUST be 1
--           or vorp_inventory never fires registerUsableItem. Every pet is rarityId 5 (Legendary).
-- Requires: VORP core items, with item_group row 1 and item_rarity row 5 present. A missing
--           group or rarity row makes INSERT IGNORE skip the item without an error.
--
-- server/pets/main.lua also creates this table on start. INSERT IGNORE leaves items you have tuned alone.
-- Safe to run more than once.

CREATE TABLE IF NOT EXISTS `pet_coats` (
  `charid` int(11) NOT NULL,
  `item` varchar(64) NOT NULL,
  `variant` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`charid`,`item`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

